# LinkedList class
class LinkedList:
    def __init__(self):
        self.head = None

    def is_empty(self):
        return self.head == None

    def add(self, data):
        node = Node(data)
        node.next = self.head
        self.head = node

    def remove(self):
        if self.is_empty():
            return None
        data = self.head.data
        self.head = self.head.next
        return data

