def palindromeArray(s): 
	res = [] 
	for i in range(1 << len(s)): 
		temp = "" 
		for j in range(len(s)): 
			# Check if jth bit is set in i 
			if (i & (1 << j)) > 0:
				temp = temp + s[j] 
		# Check if temp is palindrome
		if (temp == temp[::-1]):
			res.append(temp) 
	return res

